#include "VariationPanel.h"
namespace{const juce::Colour bg{0xff14161a},panel{0xff1c1f25},border{0xff333740},accent{0xffea5910},text{0xfff3f3f3},muted{0xffa1a5ad};}
VariationPanel::VariationPanel(juce::AudioFormatManager& f,juce::AudioThumbnailCache& c):formats(f),originalThumb(256,f,c),variationThumb(256,f,c)
{
    count.addItem("1",1);count.addItem("3",3);count.addItem("5",5);count.addItem("8",8);count.addItem("10",10);count.addItem("16",16);count.setSelectedId(5);addAndMakeVisible(count);intensity.addItem("Subtle",1);intensity.addItem("Moderate",2);intensity.addItem("Creative",3);intensity.addItem("Aggressive",4);intensity.addItem("Custom",5);intensity.setSelectedId(2);addAndMakeVisible(intensity);
    auto setupSlider=[this](juce::Slider&s,double lo,double hi,double value){s.setRange(lo,hi,.01);s.setValue(value);s.setSliderStyle(juce::Slider::LinearHorizontal);s.setTextBoxStyle(juce::Slider::TextBoxRight,false,56,20);addAndMakeVisible(s);s.onValueChange=[this]{settings.strength=(float)strength.getValue();settings.maxGainDb=(float)maxGain.getValue();settings.maxEqDb=(float)maxEq.getValue();settings.maxDriveDb=(float)maxDrive.getValue();notifyChanges();};};setupSlider(strength,0,1,.55);setupSlider(maxGain,0,12,3);setupSlider(maxEq,0,18,5);setupSlider(maxDrive,0,24,8);
    auto setupToggle=[this](juce::ToggleButton&b,const juce::String&n,bool on){b.setButtonText(n);b.setToggleState(on,juce::dontSendNotification);addAndMakeVisible(b);b.onClick=[this]{settings.allowEq=allowEq.getToggleState();settings.allowCompressor=allowComp.getToggleState();settings.allowSaturation=allowSat.getToggleState();settings.allowReverb=allowVerb.getToggleState();settings.allowDelay=allowDelay.getToggleState();settings.allowFilter=allowFilter.getToggleState();settings.allowGain=allowGain.getToggleState();notifyChanges();};};setupToggle(allowEq,"EQ",true);setupToggle(allowComp,"Compression",true);setupToggle(allowSat,"Saturation",true);setupToggle(allowVerb,"Reverb",true);setupToggle(allowDelay,"Delay",true);setupToggle(allowFilter,"Filter",true);setupToggle(allowGain,"Gain",true);
    auto setupButton=[this](juce::TextButton&b,const juce::String&n){b.setButtonText(n);b.setColour(juce::TextButton::buttonColourId,panel);b.setColour(juce::TextButton::textColourOffId,text);addAndMakeVisible(b);};setupButton(generate,"Generate Variations");setupButton(regenSelected,"Regenerate Selected");setupButton(regenUnlocked,"Regenerate Unlocked");setupButton(cancelButton,"Cancel");setupButton(playOriginal,"Play Original");setupButton(playVariation,"Play Variation");setupButton(lockButton,"Lock");setupButton(favoriteButton,"Favorite");setupButton(renameButton,"Rename");setupButton(deleteButton,"Delete");setupButton(compareButton,"A / B Original");setupButton(stopButton,"Stop");setupButton(exportButton,"Export Selected");
    count.onChange=[this]{settings.count=count.getSelectedId();notifyChanges();};intensity.onChange=[this]{settings.intensity=(VariationIntensity)(intensity.getSelectedId()-1);notifyChanges();};generate.onClick=[this]{juce::Array<int> targets;for(int n=1;n<=settings.count;++n){const Variation*latest=nullptr;for(auto&v:variations)if(v.originalSampleId==sampleId&&v.number==n&&!v.deleted)latest=&v;if(!latest||!latest->locked)targets.add(n);}renderTargets(targets);};regenSelected.onClick=[this]{renderSelected();};regenUnlocked.onClick=[this]{renderAllUnlocked();};cancelButton.onClick=[this]{cancel();};exportButton.onClick=[this]{exportSelected();};
    playOriginal.onClick=[this]{if(source.existsAsFile()&&onPreview)onPreview(source);};playVariation.onClick=[this]{const int row=list.getSelectedRow();if(juce::isPositiveAndBelow(row,variations.size())){auto f=juce::File(variations.getReference(row).outputPath);if(f.existsAsFile()&&onPreview)onPreview(f);else status.setText("Variation file is missing.",juce::dontSendNotification);}};compareButton.onClick=[this]{compareVariationNext=!compareVariationNext;if(compareVariationNext)playVariation.onClick();else playOriginal.onClick();compareButton.setButtonText(compareVariationNext?"A / B Variation":"A / B Original");};stopButton.onClick=[this]{if(onPreview)onPreview({});};
    lockButton.onClick=[this]{int row=list.getSelectedRow();if(juce::isPositiveAndBelow(row,variations.size())){auto&v=variations.getReference(row);v.locked=!v.locked;lockButton.setButtonText(v.locked?"Unlock":"Lock");notifyChanges();refresh();}};favoriteButton.onClick=[this]{int row=list.getSelectedRow();if(juce::isPositiveAndBelow(row,variations.size())){auto&v=variations.getReference(row);v.favorite=!v.favorite;favoriteButton.setButtonText(v.favorite?"Unfavorite":"Favorite");notifyChanges();refresh();}};
    renameButton.onClick=[this]{int row=list.getSelectedRow();if(!juce::isPositiveAndBelow(row,variations.size()))return;auto d=std::make_shared<juce::AlertWindow>("Rename variation","Variation name",juce::AlertWindow::NoIcon);d->addTextEditor("name",variations.getReference(row).name);d->addButton("Rename",1);d->addButton("Cancel",0);d->enterModalState(true,juce::ModalCallbackFunction::create([this,d,row](int result){if(result==1&&juce::isPositiveAndBelow(row,variations.size())){variations.getReference(row).name=d->getTextEditorContents("name").trim();notifyChanges();refresh();}}));};
    deleteButton.onClick=[this]{int row=list.getSelectedRow();if(juce::isPositiveAndBelow(row,variations.size())){auto&v=variations.getReference(row);if(v.locked){status.setText("Unlock before deleting a variation.",juce::dontSendNotification);return;}juce::File(v.outputPath).deleteFile();v.deleted=true;notifyChanges();refresh();}};
    addAndMakeVisible(list);addAndMakeVisible(progress);addAndMakeVisible(status);status.setColour(juce::Label::textColourId,muted);cancelButton.setEnabled(false);playVariation.setEnabled(false);refresh();
}
VariationPanel::~VariationPanel(){if(cancelToken)cancelToken->store(true);pool.removeAllJobs(true,5000);}
void VariationPanel::setSource(const juce::File&f,const juce::String&id,const juce::String&cat,const juce::File&a,const std::vector<EffectSettings>&base){source=f;sampleId=id;category=cat;assets=a;baseEffects=base;updateThumbnails();}
void VariationPanel::setData(const VariationSettings&s,const juce::Array<Variation>&v){settings=s;variations=v;count.setSelectedId(s.count,juce::dontSendNotification);intensity.setSelectedId((int)s.intensity+1,juce::dontSendNotification);strength.setValue(s.strength,juce::dontSendNotification);maxGain.setValue(s.maxGainDb,juce::dontSendNotification);maxEq.setValue(s.maxEqDb,juce::dontSendNotification);maxDrive.setValue(s.maxDriveDb,juce::dontSendNotification);allowEq.setToggleState(s.allowEq,juce::dontSendNotification);allowComp.setToggleState(s.allowCompressor,juce::dontSendNotification);allowSat.setToggleState(s.allowSaturation,juce::dontSendNotification);allowVerb.setToggleState(s.allowReverb,juce::dontSendNotification);allowDelay.setToggleState(s.allowDelay,juce::dontSendNotification);allowFilter.setToggleState(s.allowFilter,juce::dontSendNotification);allowGain.setToggleState(s.allowGain,juce::dontSendNotification);refresh();}
void VariationPanel::setCallbacks(StateChanged s,Preview p){onStateChanged=std::move(s);onPreview=std::move(p);}
void VariationPanel::cancelGeneration(){++generation;cancel();}
int VariationPanel::getNumRows(){return variations.size();}
void VariationPanel::paintListBoxItem(int row,juce::Graphics&g,int w,int h,bool selected){if(!juce::isPositiveAndBelow(row,variations.size()))return;const auto&v=variations.getReference(row);g.fillAll(selected?juce::Colour(0xff71300f):panel);g.setColour(v.deleted?muted:text);g.setFont(14);g.drawText(v.name+"  "+(v.locked?"🔒":"")+(v.favorite?" ★":""),10,2,w-20,22,juce::Justification::left);g.setColour(muted);g.setFont(11);g.drawText(v.deleted?"Deleted (history retained)":juce::File(v.outputPath).existsAsFile()?juce::String(v.durationSeconds,2)+" s  |  "+juce::String(v.sampleRate,0)+" Hz  |  seed "+juce::String((juce::int64)v.seed):"Missing variation file",10,24,w-20,18,juce::Justification::left);}
void VariationPanel::selectedRowsChanged(int){const int row=list.getSelectedRow();bool valid=juce::isPositiveAndBelow(row,variations.size());playVariation.setEnabled(valid&&!variations.getReference(row).deleted&&juce::File(variations.getReference(row).outputPath).existsAsFile());if(valid){const auto&v=variations.getReference(row);lockButton.setButtonText(v.locked?"Unlock":"Lock");favoriteButton.setButtonText(v.favorite?"Unfavorite":"Favorite");variationThumb.clear();if(juce::File(v.outputPath).existsAsFile())variationThumb.setSource(new juce::FileInputSource(juce::File(v.outputPath)));}repaint();}
void VariationPanel::refresh(){list.updateContent();list.repaint();}
void VariationPanel::updateThumbnails(){originalThumb.clear();if(source.existsAsFile())originalThumb.setSource(new juce::FileInputSource(source));selectedRowsChanged(list.getSelectedRow());}
void VariationPanel::notifyChanges(){if(onStateChanged)onStateChanged(settings,variations);}
void VariationPanel::save(){notifyChanges();}
void VariationPanel::renderSelected(){auto selected=list.getSelectedRows();juce::Array<int>targets;for(int i=0;i<selected.size();++i){const int row=selected[i];if(!juce::isPositiveAndBelow(row,variations.size()))continue;const auto&v=variations.getReference(row);if(v.locked||v.deleted)continue;if(!targets.contains(v.number))targets.add(v.number);}if(targets.isEmpty()){status.setText("Select at least one unlocked variation to regenerate.",juce::dontSendNotification);return;}renderTargets(targets);}
void VariationPanel::renderAllUnlocked(){juce::Array<int>t;for(int n=1;n<=settings.count;++n){const Variation*latest=nullptr;for(auto&v:variations)if(v.originalSampleId==sampleId&&v.number==n&&!v.deleted)latest=&v;if(!latest||!latest->locked)t.add(n);}renderTargets(t);}
void VariationPanel::renderTargets(juce::Array<int> targets)
{
    if(rendering)return;if(!source.existsAsFile()||sampleId.isEmpty()||!assets.isDirectory()){status.setText("Open a project and select an imported sample first.",juce::dontSendNotification);return;}if(targets.isEmpty()){status.setText("All requested variation slots are locked.",juce::dontSendNotification);return;}
    settings.seed=(juce::uint64)juce::Time::getMillisecondCounterHiRes();cancelToken=std::make_shared<std::atomic<bool>>(false);rendering=true;progressValue=0;generate.setEnabled(false);cancelButton.setEnabled(true);status.setText("Generating distinct audio variations…",juce::dontSendNotification);auto safe=juce::Component::SafePointer<VariationPanel>(this);const auto jobGeneration=generation;auto*job=new VariationRenderer(source,assets,sampleId,category,settings,baseEffects,targets,[safe,jobGeneration](juce::Array<Variation>made,const juce::String&err){if(!safe)return;if(safe->generation!=jobGeneration){for(auto&v:made)juce::File(v.outputPath).deleteFile();return;}safe->rendering=false;safe->generate.setEnabled(true);safe->cancelButton.setEnabled(false);if(!err.isEmpty()){safe->status.setText(err,juce::dontSendNotification);return;}for(auto&v:made)safe->variations.add(v);safe->status.setText("Generated "+juce::String(made.size())+" variation(s).",juce::dontSendNotification);safe->refresh();if(safe->onStateChanged)safe->onStateChanged(safe->settings,safe->variations);},[safe,jobGeneration](double p){if(safe&&safe->generation==jobGeneration){safe->progressValue=p;safe->repaint();}},cancelToken);pool.addJob(job,true);notifyChanges();
}
void VariationPanel::cancel(){if(cancelToken){cancelToken->store(true);status.setText("Cancelling; incomplete outputs will be removed.",juce::dontSendNotification);cancelButton.setEnabled(false);}}
void VariationPanel::exportSelected(){auto selected=list.getSelectedRows();if(selected.isEmpty()){status.setText("Select one or more variations to export.",juce::dontSendNotification);return;}chooser=std::make_unique<juce::FileChooser>("Export selected variations",juce::File::getSpecialLocation(juce::File::userDocumentsDirectory),"*");chooser->launchAsync(juce::FileBrowserComponent::canSelectDirectories|juce::FileBrowserComponent::openMode,[this,selected](const juce::FileChooser&c){auto dir=c.getResult();if(!dir.isDirectory())return;int copied=0;for(int i=0;i<selected.size();++i){const int row=selected[i];if(!juce::isPositiveAndBelow(row,variations.size()))continue;const auto&v=variations.getReference(row);juce::File src(v.outputPath);if(v.deleted||!src.existsAsFile())continue;auto dest=dir.getChildFile(juce::File::createLegalFileName(v.name)+"_"+v.id+src.getFileExtension());if(src.copyFileTo(dest))++copied;}status.setText("Exported "+juce::String(copied)+" variation file(s).",juce::dontSendNotification);});}
void VariationPanel::paint(juce::Graphics&g){g.fillAll(bg);auto r=getLocalBounds().reduced(12);g.setColour(panel);g.fillRoundedRectangle(r.toFloat(),10);g.setColour(border);g.drawRoundedRectangle(r.toFloat(),10,1);g.setColour(text);g.setFont(12);g.drawText("COUNT",20,4,84,14,juce::Justification::left);g.drawText("INTENSITY",112,4,130,14,juce::Justification::left);g.drawText("STRENGTH",20,43,260,14,juce::Justification::left);g.drawText("GAIN RANGE",292,43,200,14,juce::Justification::left);g.drawText("EQ RANGE",504,43,200,14,juce::Justification::left);g.drawText("DRIVE RANGE",716,43,200,14,juce::Justification::left);g.drawText("ORIGINAL WAVEFORM",20,142,300,20,juce::Justification::left);g.drawText("SELECTED VARIATION WAVEFORM",getWidth()/2+10,142,getWidth()/2-30,20,juce::Justification::left);if(originalThumb.getTotalLength()>0)originalThumb.drawChannels(g,{20,165,getWidth()/2-35,52},0,originalThumb.getTotalLength(),1);else g.drawText("Select an imported source",20,165,getWidth()/2-35,52,juce::Justification::centred);if(variationThumb.getTotalLength()>0)variationThumb.drawChannels(g,{getWidth()/2+10,165,getWidth()/2-30,52},0,variationThumb.getTotalLength(),1);else g.drawText("Select a variation",getWidth()/2+10,165,getWidth()/2-30,52,juce::Justification::centred);g.drawText("VARIATIONS / HISTORY",20,260,getWidth()-40,20,juce::Justification::left);}
void VariationPanel::resized(){const int actionX=252,actionGap=6,actionW=juce::jmax(72,(getWidth()-20-actionX-4*actionGap)/5);count.setBounds(20,20,84,28);intensity.setBounds(112,20,130,28);generate.setBounds(actionX,20,actionW,30);regenSelected.setBounds(actionX+actionW+actionGap,20,actionW,30);regenUnlocked.setBounds(actionX+2*(actionW+actionGap),20,actionW,30);cancelButton.setBounds(actionX+3*(actionW+actionGap),20,actionW,30);exportButton.setBounds(actionX+4*(actionW+actionGap),20,actionW,30);const int sliderW=(getWidth()-40-36)/4;strength.setBounds(20,58,sliderW,26);maxGain.setBounds(32+sliderW,58,sliderW,26);maxEq.setBounds(44+2*sliderW,58,sliderW,26);maxDrive.setBounds(56+3*sliderW,58,sliderW,26);const std::array<juce::ToggleButton*,7>t{{&allowEq,&allowComp,&allowSat,&allowVerb,&allowDelay,&allowFilter,&allowGain}};const int toggleW=(getWidth()-40)/7;for(int i=0;i<7;++i)t[(size_t)i]->setBounds(20+i*toggleW,94,toggleW-2,24);playOriginal.setBounds(20,222,125,28);playVariation.setBounds(151,222,135,28);compareButton.setBounds(292,222,120,28);stopButton.setBounds(418,222,70,28);list.setBounds(20,286,getWidth()-40,getHeight()-370);list.setRowHeight(44);list.setMultipleSelectionEnabled(true);lockButton.setBounds(20,getHeight()-74,95,28);favoriteButton.setBounds(122,getHeight()-74,110,28);renameButton.setBounds(239,getHeight()-74,95,28);deleteButton.setBounds(341,getHeight()-74,90,28);progress.setBounds(445,getHeight()-72,getWidth()-465,20);status.setBounds(20,getHeight()-42,getWidth()-40,20);}
